<script setup lang="ts">import {ref,computed} from 'vue';import {fixed} from '../utils/format';const props=defineProps<{result:any}>();const choice=ref(0);const path=computed(()=>props.result.morris.trajectories[choice.value]);</script><template><section class="trajectory-ledger"><div class="section-heading"><h2>网格轨迹留痕</h2><label>轨迹<select v-model.number="choice"><option v-for="(p,i) in result.morris.trajectories" :key="i" :value="i">{{p.trajectory}} / {{result.morris.trajectory_count}}</option></select></label></div><div class="table-wrap"><table><thead><tr><th>步</th><th>归一坐标 / 按模型因子顺序</th><th>变动因子</th><th>实际有符号Δ</th><th>响应 kWh</th><th>EE</th></tr></thead><tbody><tr v-for="(point,i) in path.normalized" :key="i"><td>{{i}}</td><td class="numeric-path">{{point.map((v:number)=>fixed(v,2)).join(' / ')}}</td><td>{{i?path.steps[i-1].factor_id:'起点'}}</td><td>{{i?fixed(path.steps[i-1].signed_step,4):'—'}}</td><td>{{fixed(path.responses[i],4)}}</td><td>{{i?fixed(path.steps[i-1].effect,4):'—'}}</td></tr></tbody></table></div><p class="method-note">每条轨迹每个因子恰变一次；下降步骤除以负Δ。EE使用归一坐标，已包含物理范围宽度影响。</p></section></template>
